class Solution {
public:
    bool check(vector<int>& nums) {
        int n = nums.size();

        // Edge case: n < 3 is always valid
        if (n < 3) {
            return true;
        }

        int dec = 0;

        for (int i = 1; i < n; i++) {
            if (nums[i] < nums[i - 1]) {
                dec++;
            }
        }

        // IMPORTANT: Array is circular, so also check LAST -> FIRST.
        // Example: [2,1,3,4] has 1 internal decrease (2->1)
        // but also a circular decrease (4->2), making it invalid.
        if (nums[n - 1] > nums[0]) {
            dec++;
        }

        // Sorted + rotated array can have at most ONE decrease.
        return dec < 2;
    }
};

class Solution {
public:
    bool checkStraightLine(vector<vector<int>>& coordinates) {
        int n = coordinates.size();
        if (n < 3) {
            return true;
        }

        for (int i = 2; i < n; i++) {
            int x1 = coordinates[i - 2][0];
            int x2 = coordinates[i - 1][0];
            int x3 = coordinates[i][0];
            int y1 = coordinates[i - 2][1];
            int y2 = coordinates[i - 1][1];
            int y3 = coordinates[i][1];

            if ((x1 - x2) * (y2 - y3) != (x2 - x3) * (y1 - y2)) {
                return false;
            }
        }
        return true;
    }
};

class Solution {
public:
    vector<int> getConcatenation(vector<int>& nums) {
        int n = nums.size();
        vector<int> ans(2 * n, 0);
        int i = 0;
        for (auto it : nums) {
            ans[i + n] = it;
            ans[i++] = it;
        }
        return ans;
    }
};

class Solution {
public:
    int countPrimes(int n) {
        if(n < 3){
            return 0;
        }
        vector<int> primes(1,2);

        int i = 3;
        while(i < n){
            bool prime = true;
            for(auto f: primes){
                if(i%f == 0){
                    prime = false;
                    break;
                }
            }
            if(prime){
                primes.push_back(i);
            }
            i++;
        }

        return primes.size();
    }
};

class Solution {
public:
    int findClosestNumber(vector<int>& nums) {
        int ans = -100001;
        for (auto num : nums) {
            if ((abs(ans) > abs(num)) || (abs(ans) == abs(num) && ans < num)) {
                ans = num;
            }
        }
        return ans;
    }
};

class Solution {
public:
    int findNumbers(vector<int>& nums) {
        int ans = 0;
        for (auto num : nums) {
            if (num > 9 && num < 100) {
                ans++;
            } else if (num > 999 && num < 10000) {
                ans++;
            } else if (num > 99999 && num < 1000000) {
                ans++;
            }
        }
        return ans;
    }
};

class Solution {
public:
    int pivotIndex(vector<int>& nums) {
        int sumr = 0;
        int suml = 0;
        for(auto it:nums){
            sumr+=it;
        }
        int n = nums.size();
        for(int i=0; i<n; i++){
            sumr-=nums[i];
            if(sumr == suml){
                return i;
            }
            suml+=nums[i];
        }
        return -1;
    }
};

