        seats.push_back(n);
        int i = n, ans = 0;
        n = seats.size();
        for(auto it:seats){
            cout<<it<<" ";
        }
        while (i < n - 1) {
            ans = max(ans, (seats[i + 1] - seats[i] - 2) / 2);
