    }
};

class Solution {
public:
    int maximumDifference(vector<int>& nums) {
        int ans = -1;
        int n = nums.size();
        int maxi = nums[n-1];
        int i = n-2;

        while(i >=0){
            ans = max(ans, maxi - nums[i]);
            maxi = max(maxi, nums[i]);
            i--;
        }

        return ans;

    }
};

class Solution {
public:
    long long maximumTripletValue(vector<int>& nums) {
        int n = nums.size(), largest, i;

        vector<int> leftLargest(n, 0);
        vector<int> rightLargest(n, 0);

        largest = 0;
        i = 1;
        while (i < n) {
            largest = max(largest, nums[i - 1]);
            leftLargest[i] = largest;
            i++;
        }

        largest = 0;
        i = n - 2;

        while (i >= 0) {
            largest = max(largest, nums[i + 1]);
            rightLargest[i] = largest;
            i--;
        }

        long long ans = 0;
        i = 1;
        while (i < n - 1) {
            long long I = leftLargest[i];
            long long J = nums[i];
            long long K = rightLargest[i];
            ans = max(ans, K * (I - J));
            i++;
        }

        return ans;
    }
};

class Solution {
public:
    void resort(vector<int>& nums, int n) {
        int i = 0, last = nums[n - 1];
        while (i < n - 1 && nums[i] <= last) {
            i++;
        }
        int j = n - 1;
        while (j > i) {
            nums[j] = nums[j - 1];
            j--;
        }
        nums[j] = last;
    }
    void add1s(vector<int>& nums, int n) {
        for (auto& num : nums) {
            num++;
        }
        nums[n - 1]--;
    }
    int minMoves(vector<int>& nums) {
        int n = nums.size();
        sort(nums.begin(), nums.end());

        int ans = 0;
        while (nums[0] != nums[n - 1]) {
            add1s(nums, n);
            ans++;
            resort(nums, n);
        }

        return ans;
    }
};

class Solution {
public:
    bool isMonotonic(vector<int>& nums) {
        int n = nums.size();
        if (n < 3) {
            return true;
        }
        bool inc = true, dec = true;
        int i = 1;
        while (i < n) {
            if (nums[i - 1] > nums[i]) {
                inc = false;
            }
            if (nums[i - 1] < nums[i]) {
                dec = false;
            }
            i++;
        }
        return inc || dec;
    }
};

class Solution {
public:
    bool checkPossibility(vector<int>& nums) {
        int n = nums.size();
        if (n < 3) {
            return true;
        }
        int exp = 0, real = 0, i = 0;
        while (i < n - 1) {
            if (nums[i] <= nums[i + 1]) {
                real++;
            }
            exp++;
            i++;
        }
        return exp - real < 2;
    }
};

class Solution {
public:
    int waysToSplitArray(vector<int>& nums) {
        int n = nums.size();
        if (n < 2) {
            return 0;
        }
        long long sumr = 0, suml = 0;
        for (auto it : nums) {
            sumr += it;
        }
        int i = 0, ans = 0;

        while (i < n - 1) {
            suml += nums[i];
            sumr -= nums[i];
            if (suml >= sumr) {
                ans++;
            }
            i++;
        }

        return ans;
    }
};

class Solution {
public:
    long long zeroFilledSubarray(vector<int>& nums) {
        vector<int> idx(1, 0);
        int i = 1;
        for (auto it : nums) {
            if (it != 0) {
                idx.push_back(i);
            }
            i++;
        }
        idx.push_back(nums.size() + 1);

        int n = idx.size();
        i = 1;

        long long ans = 0;
        while (i < n) {
            long long a = idx[i] - idx[i - 1];
            ans += ((a - 1) * a) / 2;
            i++;
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> plusOne(vector<int>& digits) {
        int carry = 1, n = digits.size();

        reverse(digits.begin(), digits.end());

        for(auto &num: digits){
            carry+= num;
            num = carry%10;
            carry/=10;
        }

        while(carry > 0){
            digits.push_back(carry%10);
            carry/=10;
        }

        reverse(digits.begin(), digits.end());

        return digits;

    }
};

class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        int n = nums.size();
        vector<int> left(n, 1), right(n, 1), ans(n, 1);

        for (int i = 1; i < n; i++) {
            left[i] = left[i - 1] * nums[i - 1];
            right[n - i - 1] = right[n - i] * nums[n - i];
        }

        for (int i = 0; i < n; i++) {
            ans[i] = left[i] * right[i];
        }

        return ans;
    }
};

