class Solution {
public:
    vector<int> replaceElements(vector<int>& arr) {
        int maxi = -1;
        int n = arr.size();
        int i = n - 1;
        while (i >= 0) {
            int temp = arr[i];
            arr[i] = maxi;
            maxi = max(maxi, temp);
            i--;
        }
        return arr;
    }
};

class Solution {
public:
    vector<int> runningSum(vector<int>& nums) {
        int sum = 0;
        for(auto &num:nums){
            sum+=num;
            num=sum;
        }
        return nums;
    }
};

#define ALPHA 26000000

class Solution {
public:
    char shiftChar(char ch, int num) {
        return 'a' + (ALPHA + num + ch - 'a') % 26;
    }
    string shiftingLetters(string s, vector<vector<int>>& shifts) {
        int n = s.size();
        int i = 0;

        unordered_map<int, int> mp;

        while (i < n) {
            mp[i++] = 0;
        }

        for (auto it : shifts) {
            i = it[0];
            while (i <= it[1]) {
                mp[i++] += it[2] * 2 - 1;
            }
        }

        i = 0;
        for (auto& ch : s) {
            ch = shiftChar(ch, mp[i++]);
        }

        return s;
    }
};

class Solution {
public:
    vector<int> shuffle(vector<int>& nums, int n) {
        vector<int> ans(2 * n, 0);
        int i = 0;
        while (i < n) {
            ans[2 * i] = nums[i];
            ans[2 * i + 1] = nums[i + n];
            i++;
        }
        return ans;
    }
};

class Solution {
public:
    vector<string> summaryRanges(vector<int>& nums) {
        int n = nums.size();
        if (n == 0) {
            return {};
        }
        if (n == 1) {
            return {to_string(nums[0])};
        }

        vector<vector<int>> mat;
        mat.push_back({});
        mat[0].push_back(nums[0]);

        int i = 1;
        int r = 0;
        int c = 0;
        while (i < n) {
            if (nums[i] == mat[r][c] + 1) {
                mat[r].push_back(nums[i]);
                c++;
            } else {
                mat.push_back({});
                r++;
                mat[r].push_back(nums[i]);
                c = 0;
            }
            i++;
        }

        vector<string> ans;
        for (auto& it : mat) {
            int a = it[0];
            int b = it[it.size() - 1];

            if (a < b) {
                ans.push_back(to_string(a) + "->" + to_string(b));
            } else {
                ans.push_back(to_string(a));
            }
        }

        return ans;
    }
};

class Solution {
public:
    string generateGap(int n) {
        string gap(n, ' ');
        return gap;
    }
    string createLine(vector<string>& lineWords, int totalGap) {
        int n = lineWords.size();
        if (lineWords.size() == 1) {
            return lineWords[0] + generateGap(totalGap);
        }
        string gaps = generateGap(totalGap / (n - 1));
        string firstGap = gaps + generateGap(totalGap % (n - 1));

        string line = "";

        for (int i = 0; i < n; i++) {
            if (i == 0) {
                line += lineWords[i] + firstGap;
            } else if (i == n - 1) {
                line += lineWords[i];
            } else {
                line += lineWords[i] + gaps;
            }
        }

        return line;
    }
    vector<string> fullJustify(vector<string>& words, int maxWidth) {
        int l = 0;
        int wordsLength = 0;
        vector<string> temp;
        vector<string> ans;

        for (auto str : words) {
            if (l == 0) {
                temp = {str};
                l = str.size();
                wordsLength = str.size();
            } else if (l + str.size() + 1 > maxWidth) {
                ans.push_back(createLine(temp, maxWidth - wordsLength));
                temp = {str};
                l = str.size();
                wordsLength = str.size();
            } else {
                temp.push_back(str);
                l += str.size() + 1;
                wordsLength += str.size();
            }
        }
        if (l > 0) {
            ans.push_back(createLine(temp, maxWidth - wordsLength));
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> threeEqualParts(vector<int>& arr) {
        int ones = 0;
        for (auto num : arr) {
            ones += num;
        }
        if (ones % 3 != 0) {
            return {-1, -1};
        }
        if (ones == 0) {
            return {0, 2};
        }

        int i = 0, j = 0, k = 0, n = arr.size(), temp = 0;

        while (k < n) {
            if (arr[k] == 1) {
                temp++;
            }
            if (temp <= ones / 3) {
                i++;
            }
            if (temp <= 1 + (2 * ones) / 3) {
                j++;
            }
            k++;
        }

        int l = min(i + 1, min(j - 1 - i, n - j));

        int x = i, y = j - 1, z = n - 1;

        while (l > 0) {
            if (arr[x] != arr[y] || arr[z] != arr[y] || arr[x] != arr[z]) {
                return {-1, -1};
            }
            x--;
            y--;
            z--;
            l--;
        }

        return {i, j};
    }
};

class Solution {
public:
    bool validMountainArray(vector<int>& arr) {
        int n = arr.size();
        if (n < 3) {
            return false;
        }
        int i = 0;
        while (i < n - 1 && arr[i] < arr[i + 1]) {
            i++;
        }
        int j = n - 1;
        while (j > 0 && arr[j] < arr[j - 1]) {
            j--;
        }
        return i == j && i > 0 && i < n - 1;
    }
};

class Solution {

    // k < (sqrt(8n + 1) - 1)/2

public:
    int arrangeCoins(int n) {
        long long k = n;
        double sqr = abs(sqrt(8 * k + 1));
        return floor((sqr - 1) / 2);
    }
};

// The API isBadVersion is defined for you.
// bool isBadVersion(int version);

class Solution {
public:
    int firstBadVersion(int n) {
        int i = 1, j = n;
        int bv = 0;
        while (i <= j) {
            int k = i + (j - i) / 2;
            bool isBad = isBadVersion(k);
            if (isBad) {
                bv = k;
                j = k - 1;
            } else {
                if (bv > 0) {
                    break;
                } else {
                    i = k + 1;
                }
            }
        }
        return bv;
    }
};

class Solution {
public:
    int mySqrt(int x) {
        if (x < 2) {
            return x;
        }
        int i = 1, j = x;
        while (i <= j) {
            long long k = i + (j - i) / 2;
            if (k * k <= x && (k + 1) * (k + 1) > x) {
                return k;
            } else if (k * k > x) {
                j = k - 1;
            } else {
                i = k + 1;
            }
        }
        return x;
    }
};

class Solution {
public:
    bool isPerfectSquare(int num) {
        if (num == 1) {
            return true;
        }

        int i = 2, j = num - 1;

        while (i <= j) {

            long long k = i + (j - i) / 2;
            long long sq = k * k;

            if (sq == num) {
                return true;
            } else if (sq > num) {
                j = k - 1;
            } else {
                i = k + 1;
            }
        }
        return false;
    }
};

class BrowserHistory {
    int current;
    vector<string> history;

public:
    BrowserHistory(string homepage) {
        current = 0;
        history.push_back(homepage);
    }

    // void visit(string url) {
    //     vector<string> new_history(history.begin(),
    //                                history.begin() + current + 1);
    //     new_history.push_back(url);
    //     current++;
    //     history = new_history;
    // }

    void visit(string url) {
        history.erase(history.begin() + current + 1, history.end());
        history.push_back(url);
        current++;
    }

    string back(int steps) {
        current = max(0, current - steps);
        return history[current];
    }

    string forward(int steps) {
        int n = history.size();
        current = min(n - 1, current + steps);
        return history[current];
    }
};

