class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int n = prices.size();
        if (n < 2) {
            return 0;
        }

        int maxi = prices[n - 1];
        int profit = 0;
        n -= 2;

        while (n >= 0) {
            profit = max(profit, maxi - prices[n]);
            maxi = max(maxi, prices[n]);
            n--;
        }

        return profit;
    }
};

#define MAX 10001
class Solution {
public:
    int recur(vector<int>& coins, int amount) {
        if (amount == 0) {
            return 0;
        }
        if (amount < 0) {
            return MAX;
        }
        int ans = MAX;
        for (auto coin : coins) {
            ans = min(ans, 1 + recur(coins, amount - coin));
        }
        return ans;
    }
    int use_recur(vector<int>& coins, int amount) {
        int ans = recur(coins, amount);
        return ans == MAX ? -1 : ans;
    }
    int memo(vector<int>& coins, int amount, vector<int>& dp) {
        if (amount == 0) {
            return 0;
        }
        if (amount < 0) {
            return MAX;
        }
        if (dp[amount] < MAX) {
            return dp[amount];
        }
        int ans = MAX;
        for (auto coin : coins) {
            ans = min(ans, 1 + memo(coins, amount - coin, dp));
        }
        return dp[amount] = ans;
    }
    int use_memo(vector<int>& coins, int amount) {
        vector<int> dp(amount + 1, MAX);
        int ans = memo(coins, amount, dp);
        return ans == MAX ? -1 : ans;
    }
    int tab(vector<int>& coins, int amount) {
        vector<int> dp(amount + 1, MAX);
        dp[0] = 0;
        int i = 1;
        while (i <= amount) {
            for (auto coin : coins) {
                if (i >= coin) {
                    dp[i] = min(dp[i], 1 + dp[i - coin]);
                }
            }
            i++;
        }
        return dp[amount] == MAX ? -1 : dp[amount];
    }
    int coinChange(vector<int>& coins, int amount) {
        // return use_recur(coins, amount);
        // return use_memo(coins, amount);
        return tab(coins, amount);
    }
};

class Solution {
public:
    bool buddyStrings(string s, string goal) {
        int n = s.size();

        vector<int> freq(26, 0);
        bool flag = false;

        if (goal.size() != n) {
            return false;
        }
        vector<int> diff;
        int i = 0;
        while (i < n) {
            if (s[i] != goal[i]) {
                diff.push_back(i);
            }
            freq[s[i] - 'a']++;
            if (freq[s[i] - 'a'] > 1) {
                flag = true;
            }
            i++;
        }
        if (diff.size() == 0) {
            return flag;
        }
        if (diff.size() == 2) {
            int j = diff[0], k = diff[1];
            return s[j] == goal[k] && goal[j] == s[k];
        }
        return false;
    }
};

