class Solution {
public:
    bool containsNearbyDuplicate(vector<int>& nums, int k) {
        unordered_map<int, int> mp;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            if (mp.contains(nums[i]) && i - mp[nums[i]] <= k) {
                return true;
            }
            mp[nums[i]] = i;
        }
        return false;
        ;
    }
};

class UndergroundSystem {
    // unordered_map<pair<string, string>, pair<double, int>> mean; 
    // RCA: unordered_map requires a hash function for its key;
    // std::hash<pair<string,string>> isn't provided by default, 
    // so a custom hash is required for a pair key.
    unordered_map<string, pair<double, int>> mean;
    unordered_map<int, pair<string, int>> transit;

public:
    void checkIn(int id, string stationName, int t) {
        transit[id] = {stationName, t};
    }

    void checkOut(int id, string stationName, int t) {
        string old_station = transit[id].first;
        if (!mean.contains(old_station + "-" + stationName)) {
            mean[old_station + "-" + stationName] = {0, 0};
        }

        double average = mean[old_station + "-" + stationName].first;
        int count = mean[old_station + "-" + stationName].second;

        int old_time = transit[id].second;

        average = (average * count + t - old_time) / (count + 1);
        count++;

        mean[old_station + "-" + stationName] = {average, count};
    }

    double getAverageTime(string startStation, string endStation) {
        return mean[startStation + "-" + endStation].first;
    }
};

