class Solution {
public:
    bool isIsomorphic(string s, string t) {
        int n = s.size();
        if(n < 2){
            return true;
        }

        unordered_map<char,char> mp1;
        unordered_map<char,char> mp2;

        for(int i = 0; i < n; i++){
            char chs = s[i];
            char cht = t[i];

            if(mp1.contains(chs) && mp1[chs] != cht){
                return false;
            }
            if(mp2.contains(cht) && mp2[cht] != chs){
                return false;
            }

            mp1[chs] = cht;
            mp2[cht] = chs;
        }

        return true;
    }
};

