class Solution {
public:
    int findLHS(vector<int>& nums) {
        map<int, int> mp;
        for (auto num : nums) {
            mp[num]++;
        }
        int lastVal = mp.begin()->first;
        int ans = 0;
        for (auto it : mp) {
            if (it.first - lastVal == 1) {
                ans = max(ans, it.second + mp[lastVal]);
            }
            lastVal = it.first;
        }
        return ans;
    }
};

