class Solution {
public:
    string mostCommonWord(string paragraph, vector<string>& banned) {
        unordered_map<string, int> mp;
        string str = "";
        for (auto ch : paragraph) {
            if (isalpha(ch)) {
                str.push_back(tolower(ch));
            } else {
                if (str.size() > 0) {
                    mp[str]++;
                    str = "";
                }
            }
        }
        if (str.size() > 0) {
            mp[str]++;
            str = "";
        }

        for (auto word : banned) {
            for (auto& ch : word) {
                tolower(ch);
            }
            mp[word] = -1;
        }
        string ans = "";
        mp[""] = -1;

        for (auto it : mp) {
            if (it.second > mp[ans]) {
                ans = it.first;
            }
        }

        return ans;
    }
};

class Solution {
public:
    int numIdenticalPairs(vector<int>& nums) {
        unordered_map<int, int> mp;
        for (auto it : nums) {
            mp[it]++;
        }
        int ans = 0;
        for (auto it : mp) {
            int n = it.second;
            ans += (n * (n - 1)) / 2;
        }
        return ans;
    }
};

class Solution {
public:
    vector<int> arrayRankTransform(vector<int>& arr) {
        map<int, int> mp;
        int i = 0;
        for (auto it : arr) {
            mp[it] = 0;
        }
        i = 1;
        for (auto& it : mp) {
            it.second = i++;
        }
        for (auto& it : arr) {
            it = mp[it];
        }
        return arr;
    }
};

