class Solution {
public:
    void setZeroes(vector<vector<int>>& matrix) {
        unordered_map<int, bool> iz;
        unordered_map<int, bool> jz;

        int m = matrix.size();
        int n = matrix[0].size();

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == 0) {
                    iz[i] = true;
                    jz[j] = true;
                }
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (iz[i] || jz[j]) {
                    matrix[i][j] = 0;
                }
            }
        }
    }
};

class TimeMap {
    unordered_map<string, map<int, string>> mp;

public:
    TimeMap() {}

    void set(string key, string value, int timestamp) {
        if (!mp.contains(key)) {
            map<int, string> me;
            mp[key] = me;
        }
        mp[key][timestamp] = value;
    }

    string get(string key, int timestamp) {
        if (mp.contains(key)) {

            auto it = mp[key].end();
            it--; // RCA: map.end() points past the last element, so it cannot
                  // be dereferenced (it->first); decrement it first to access
                  // the last element.

            while (it->first > timestamp) {
                if (it == mp[key].begin()) {
                    return "";
                }
                it--;
            }

            return it->second;
        }
        return "";
    }
};

