class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int,int> mp;
        int i = 0;
        for(auto it:nums){
            if(mp.contains(target - it)){
                return {mp[target-it],i};
            }
            mp[it] = i++;
        }
        return {};
    }
};

class Solution {
public:
    int numUniqueEmails(vector<string>& emails) {
        unordered_set<string> st;
        for (auto email : emails) {

            bool plus = false;
            bool atrate = false;

            string str = "";
            for (auto ch : email) {
                if (ch == '+') {
                    plus = true;
                }
                if (ch == '@') {
                    atrate = true;
                }
                if ((!plus && !atrate && ch != '.') || atrate) {
                    str.push_back(ch);
                }
            }

            st.insert(str);
        }
        return st.size();
    }
