            }
        }
        return true;
    }
};

class Solution {
public:
    bool isAlienSorted(vector<string>& words, string order) {
        unordered_map<char, char> alien_to_human;
        vector<string> human_words;
        int i = 0, n = words.size();
        for (auto ch : order) {
            alien_to_human[ch] = 'a' + i++;
        }
        for (auto& word : words) {
            int j = 0, m = word.size();
            while (j < m) {
                word[j] = alien_to_human[word[j]];
                j++;
            }
            human_words.push_back(word);
        }
        sort(human_words.begin(), human_words.end());
        i = 0;

        while (i < n) {
            if (words[i] != human_words[i]) {
                return false;
            }
            i++;
        }

        return true;
    }
};

class Solution {
public:
    bool wordPattern(string pattern, string s) {
        int i = -1, j = -1, n = s.size(), m = pattern.size();
        vector<string> words;
        for(int k = 0; k < n; k++){
            if(s[k] != ' '){
                if(i == -1){
                    if(k == 0){
                        i = k;
                    }
                    if(k > 0 && s[k-1] == ' '){
                        i = k;
                    }
                }
                if(j == -1){
                    if(k == n-1){
                        j = k;
                    }
                    if(k < n-1 && s[k+1] == ' '){
                        j = k;
                    }
                }
            }
            if(i >= 0 && j >= 0){
                words.push_back(s.substr(i, j - i + 1));
                i = -1; j = -1;
            }
        }
        if(words.size() != m){
            return false;
        }

        unordered_map<string,char> mpsc;
        unordered_map<char,string> mpcs;

        for(int i = 0; i < m; i++){
            char ch = pattern[i];
            string word = words[i];
            if(mpcs.contains(ch) && mpcs[ch] != word){
                return false;
            }
            mpcs[ch] = word;
            if(mpsc.contains(word) && mpsc[word] != ch){
                return false;
            }
            mpsc[word] = ch;
        }

        return true;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        if (l1 == nullptr) {
            return l2;
        }
        if (l2 == nullptr) {
            return l1;
        }

        stack<int> s1, s2, s3;

        while (l1 != nullptr) {
            s1.push(l1->val);
            l1 = l1->next;
        }
        while (l2 != nullptr) {
            s2.push(l2->val);
            l2 = l2->next;
        }

        int sum = 0;
        while (!s1.empty() && !s2.empty()) {
            sum += s1.top();
            s1.pop();
            sum += s2.top();
            s2.pop();
            s3.push(sum % 10);
            sum /= 10;
        }
        while (!s1.empty()) {
            sum += s1.top();
            s1.pop();
            s3.push(sum % 10);
            sum /= 10;
        }
        while (!s2.empty()) {
            sum += s2.top();
            s2.pop();
            s3.push(sum % 10);
            sum /= 10;
        }
        while (sum > 0) {
            s3.push(sum % 10);
            sum /= 10;
        }
        ListNode* head = nullptr;
        ListNode* temp = nullptr;

        while (!s3.empty()) {
            ListNode* node = new ListNode(s3.top());
            s3.pop();
            if (head == nullptr) {
                head = node;
                temp = node;
            } else {
                temp->next = node;
                temp = temp->next;
            }
        }
        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    int getDecimalValue(ListNode* head) {
        while (head->val == 0) {
            head = head->next;
            if (head == nullptr) {
                return 0;
            }
        }

        vector<int> arr;
        while (head != nullptr) {
            arr.push_back(head->val);
            head = head->next;
        }

        int ans = 0, n = arr.size();
        for (int i = 0; i < n; i++) {
            ans += arr[i] ? pow(2, n - 1 - i) : 0;
        }

        return ans;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    void deleteNode(ListNode* node) {
        while (node->next->next != nullptr) {
            node->val = node->next->val;
            node = node->next;
        }
        node->val = node->next->val;
        node->next = nullptr;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* modifiedList(vector<int>& nums, ListNode* head) {
        unordered_set<int> st;
        for (auto num : nums) {
            st.insert(num);
        }
        while (st.contains(head->val)) {
            head = head->next;
        }
        auto temp = head;
        while (temp != nullptr && temp->next != nullptr) {
            if (st.contains(temp->next->val)) {
                temp->next = temp->next->next;
            } else {
                temp = temp->next;
            }
        }
        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* deleteMiddle(ListNode* head) {
        if (head == nullptr || head->next == nullptr) {
            return nullptr;
        }

        int n = 0;
        auto temp = head;
        while (temp != nullptr) {
            n++;
            temp = temp->next;
        }
        int m = (n / 2) - 1;
        temp = head;
        while (m > 0) {
            temp = temp->next;
            m--;
        }
        auto del = temp->next;
        temp->next = temp->next->next;
        del->next = nullptr;
        return head;
    }
};

