class Node {
public:
    int val;
    Node* next;
    Node(int val) {
        this->val = val;
        next = nullptr;
    }
};

class MyLinkedList {
    Node* head;

public:
    MyLinkedList() { head = nullptr; }

    void printList(){
        auto temp = head;
        while(temp!=nullptr){
            cout<<head->val<<" ";
        }
        cout<<endl;
    }

    int get(int index) {
        while (index > 0 && head != nullptr) {
            head = head->next;
            index--;
        }
        if (head != nullptr) {
            return head->val;
        }
        return -1;
    }

    void addAtHead(int val) {
        Node* new_node = new Node(val);
        new_node->next = head;
        head = new_node;
    }

    void addAtTail(int val) {
        Node* new_node = new Node(val);
        if (head == nullptr) {
            head = new_node;
        } else {
            auto temp = head;
            while (temp->next != nullptr) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    }

    void addAtIndex(int index, int val) {
        if (index == 0) {
            addAtHead(val);
        } else {
            index--;
            auto temp = head;
            while (index > 0) {
                temp = temp->next;
                index--;
            }
            Node* new_node = new Node(val);
            new_node->next = temp->next;
            temp->next = new_node;
        }
    }

    void deleteAtIndex(int index) {
        if (index == 0) {
            auto temp = head;
            head = head->next;
            temp->next = nullptr;
        } else {
            index--;
            auto temp = head;
            while (index > 0) {
                temp = temp->next;
                index--;
            }
            auto del = temp->next;
            temp->next = del->next;
            del = nullptr;
        }
    }
};

