/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* doubleIt(ListNode* head) {
        stack<int> st1, st2;
        int sum = 0;
        while (head != nullptr) {
            sum += head->val;
            head = head->next;
            st1.push(sum % 10);
            sum /= 10;
        }
        while (sum > 0) {
            st1.push(sum % 10);
            sum /= 10;
        }
        while (!st1.empty()) {
            sum += 2 * st1.top();
            st1.pop();
            st2.push(sum % 10);
            sum /= 10;
        }
        while (sum > 0) {
            st2.push(sum % 10);
            sum /= 10;
        }
        head = nullptr;
        ListNode* tail = nullptr;
        while (!st2.empty()) {
            ListNode* node = new ListNode(st2.top());
            st2.pop();
            if (head == nullptr) {
                head = node;
                tail = node;
            } else {
                tail->next = node;
                tail = tail->next;
            }
        }
        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* insert(ListNode* head, ListNode* node) {
        if (node->val < head->val) {
            node->next = head;
            return node;
        }
        ListNode* temp = head;
        while (temp->next != nullptr && node->val >= temp->next->val) {
            temp = temp->next;
        }
        node->next = temp->next;
        temp->next = node;
        return head;
    }
    ListNode* insertionSortList(ListNode* head) {
        ListNode* sorted = head;
        head = head->next;
        sorted->next = nullptr;
        while (head != nullptr) {
            ListNode* temp = head;
            head = head->next;
            temp->next = nullptr;
            sorted = insert(sorted, temp);
        }
        return sorted;
    }
};

