        ListNode* slow = head;
        ListNode* fast = head;

        while (slow != NULL && fast != NULL) {
            slow = slow->next;
            fast = fast->next;

            if (fast != NULL) {
                fast = fast->next;
            } else {
                break;
            }

            if (slow == fast) {
                return true;
