        }
        return false;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
public:
    ListNode* detectCycle(ListNode* head) {
        if (head == nullptr || head->next == nullptr) {
            return nullptr;
        }

        auto s = head, f = head;

        while (f != nullptr && f->next != nullptr) {
            s = s->next;
            f = f->next->next;
            if (f == s) {
                break;
            }
        }
        if (s != f || f == nullptr) {
            return nullptr;
        }
        s = head;
        while (s != f) {
            s = s->next;
            f = f->next;
        }
        return f;
    }
};

