 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverse(ListNode* head) {
        ListNode* temp = nullptr;
        while (head != nullptr) {
            auto node = head;
            head = head->next;
            node->next = temp;
            temp = node;
        }
        return temp;
    }
    int pairSum(ListNode* head) {
        auto f = head, s = head;
        while (f->next != nullptr && f->next->next != nullptr) {
            s = s->next;
            f = f->next->next;
        }
        auto left = head;
        auto right = reverse(s->next);
        int ans = 0;
        while (right != nullptr) {
            ans = max(ans, left->val + right->val);
            left = left->next;
            right = right->next;
        }
        return ans;
    }
};

