        auto A = list1, B = list1;
        while (a > 1) {
            a--;
            A = A->next;
        }
        while (b >= 0) {
            b--;
            B = B->next;
        }
        A->next = list2;
        while (list2->next != nullptr) {
            list2 = list2->next;
        }
        list2->next = B;
        B = nullptr;
        return list1;
    }
};

