 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* partition(ListNode* head, int x) {
        ListNode* left = nullptr;
        ListNode* right = nullptr;
        ListNode* i = nullptr;
        ListNode* j = nullptr;
        ListNode* temp = head;

        while(temp!=nullptr){
            ListNode* node = temp;
            temp = temp->next;
            node->next = nullptr;
            if(node->val < x){
                if(left == nullptr){
                    left = node;
                    i = node;
                }else{
                    i->next = node;
                    i = i->next;
                }
            }else{
                if(right == nullptr){
                    right = node;
                    j = node;
                }else{
                    j->next = node;
                    j = j->next;
                }

            }

        }
        if(i!=nullptr){
            i->next = right;
            return left;
        }
        return right;
    }
};

