};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* deleteDuplicates(ListNode* head) {

        unordered_map<int, int> freq;
        auto temp = head;
        while (temp != nullptr) {
            freq[temp->val]++;
            temp = temp->next;
        }

        while (head != nullptr && freq[head->val] > 1) {
            temp = head;
            head = head->next;
            temp->next = nullptr;
        }

        temp = head;
        while (temp != nullptr && temp->next != nullptr) {
            if (freq[temp->next->val] > 1) {
                auto dup = temp->next;
                temp->next = temp->next->next;
                dup->next = nullptr;
            } else {
                temp = temp->next;
            }
        }

        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        int n = 0;
        auto temp = head;

        while (temp != nullptr) {
            n++;
            temp = temp->next;
        }

        if (n == 0) {
            return head;
        }

        k %= n;
        if (k == 0) {
            return head;
        }

        k = n - k - 1;
        temp = head;
        while (k > 0) {
            temp = temp->next;
            k--;
        }

        auto newhead = temp->next;
        temp->next = nullptr;

        temp = newhead;

        while (temp->next != nullptr) {
            temp = temp->next;
        }

        temp->next = head;

        return newhead;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        if(head == nullptr){
            return head;
        }

        int n = 0;
        auto temp = head;
        while (temp != nullptr) {
            n++;
            temp = temp->next;
        }

        k = k % n;

        if (k == 0) {
            return head;
        }

        int m = n + n - k - 1, i = 0;
        temp = head;

        while (i < m) {
            temp = temp->next;
            i++;

            if (temp->next == nullptr) {
                temp->next = head;
            }
        }

        head = temp->next;
        temp->next = nullptr;

        return head;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    vector<ListNode*> splitListToParts(ListNode* head, int k) {
        int n = 0;
        auto temp = head;
        while (temp != nullptr) {
            n++;
            temp = temp->next;
        }

        vector<int> length(k, n / k);
        int extra = n % k;
        while (extra > 0) {
            length[--extra]++;
        }
        for (auto num : length) {
            cout << num << " ";
        }

        vector<ListNode*> heads(k, nullptr);
        vector<ListNode*> tails(k, nullptr);
        for (int i = 0; i < k; i++) {
            if (head == nullptr) {
                break;
            }
            while (head != nullptr && length[i] > 0) {
                temp = head;
                head = head->next;
                temp->next = nullptr;
                length[i]--;
                if (heads[i] == nullptr) {
                    heads[i] = temp;
                    tails[i] = temp;
                } else {
                    tails[i]->next = temp;
                    tails[i] = tails[i]->next;
                }
            }
        }
        return heads;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* swapNodes(ListNode* head, int k) {
        int n = 0;
        auto temp = head;

        while (temp != nullptr) {
            n++;
            temp = temp->next;
        }

        auto left = head, right = head;
        int m = k - 1, p = n - k;

        while (m > 0) {
            left = left->next;
            m--;
        }

        while (p > 0) {
            right = right->next;
            p--;
        }

        int t = left->val;
        left->val = right->val;
        right->val = t;

        return head;
    }
};

