class Solution {
public:
    vector<vector<int>> construct2DArray(vector<int>& original, int m, int n) {
        int k = original.size();
        vector<vector<int>> mat;

        if (k != m * n) {
            return mat;
        }

        vector<int> arr;
        for (int i = 0; i < k; i++) {
            arr.push_back(original[i]);
            if ((i + 1) % n == 0) {
                mat.push_back(arr);
                arr.clear();
            }
        }

        if (arr.size() > 0 && mat.size() < m) {
            mat.push_back(arr);
        }

        return mat;
    }
};

class Solution {
public:
    int countNegatives(vector<vector<int>>& grid) {
        int n = grid.size();
        int m = grid[0].size();
        int ans = 0;
        for(auto vec:grid){
            int i = 0;
            while(i < m){
                if(vec[i] < 0){
                    ans+=m-i;
                    break;
                }
                i++;
            }
        }
        return ans;
    }
};

class Solution {
public:
    int diagonalSum(vector<vector<int>>& mat) {
        int ans = 0, n = mat.size();
        for (int i = 0; i < n; i++) {
            ans += mat[i][i];
        }
        for (int i = n - 1; i >= 0; i--) {
            ans += 2*i == n - 1 ? 0 : mat[i][n - 1 - i];
        }
        return ans;
    }
};

