class Solution {
public:
    int firstUniqChar(string s) {
        vector<int> firstIndex(26, -1);
        vector<int> counts(26, 0);
        int i = 0;
        for (auto ch : s) {
            int k = ch - 'a';
            if (firstIndex[k] < 0) {
                firstIndex[k] = i;
            }
            counts[k]++;
            i++;
        }
        int ans = s.size();
        for (i = 0; i < 26; i++) {
            if (counts[i] == 1) {
                ans = min(ans, firstIndex[i]);
            }
        }
        return ans < s.size() ? ans : -1;
    }
};

