class Solution {
public:
    vector<int> merge(vector<int>&v1,vector<int>&v2){
        vector<int> v;
        int i = 0, j = 0, n = v1.size(), m = v2.size();
        while(i < n || j < m){
            if(i < n){
                v.push_back(v1[i++]);
            }
            if(j < m){
                v.push_back(v2[j++]);
            }
        }
        return v;
    }
    vector<int> deckRevealedIncreasing(vector<int>& deck) {
        int n = deck.size();
        if (n == 1) {
            return deck;
        }
        sort(deck.begin(), deck.end());
        vector<vector<int>> mat;
        int i = 0;
        int j = 0;
        while (n >= 1) {
            int m = (n + 1) / 2;
            vector<int> sub(deck.begin() + i, deck.begin() + i + m);
            if (j % 2 == 1) {
                reverse(sub.begin(), sub.end());
            }
            mat.push_back(sub);
            n -= m;
            i += m;
            j++;
        }
        int k = mat.size();
        if(k == 1){
            return mat[0];
        }
        vector<int> temp = mat[k-1];
        k-=2;
        while(k >= 0){
            temp = merge(mat[k--],temp);
        }
        return temp;
    }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        if(head == nullptr){
            return head;
        }
        auto rev = head;
        head = head->next;
        rev->next = nullptr;
        while(head!=nullptr){
            auto temp = head->next;
            head->next = rev;
            rev = head;
            head = temp;
        }
        return rev;
    }
};

