        int i = 0;
        sort(citations.begin(),citations.end());
        while(i < n){
            ans = max(ans, min(citations[i], n-i));
            i++;
        }
        return ans; 
    }
};

class Solution {
public:
    int heightChecker(vector<int>& heights) {
        int n = heights.size();
        vector<int> expected;
        for (auto it : heights) {
            expected.push_back(it);
        }
        sort(expected.begin(), expected.end());
        int ans = 0;

        for (int i = 0; i < n; i++) {
            ans += expected[i] == heights[i] ? 0 : 1;
        }
        return ans;
    }
};

class Solution {
public:
    int maximumGap(vector<int>& nums) {
        int n = nums.size();
        if (n < 2) {
            return 0;
        }
        sort(nums.begin(), nums.end());
        int i = 1;
        int ans = 0;
        while (i < n) {
            ans = max(ans, nums[i] - nums[i - 1]);
            i++;
        }
        return ans;
    }
};

class Solution {
public:
    double trimMean(vector<int>& arr) {
        sort(arr.begin(), arr.end());
        int n = arr.size();
        int i = n / 20, j = n - 1 - n / 20, k = (9 * n) / 10;
        double ans = 0;
        while (i <= j) {
            double tmp = arr[i++];
            ans += tmp / k;
        }
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end(),
             [](vector<int>& a, vector<int>& b) {
                 return a[0] == b[0] ? a[1] < b[1] : a[0] < b[0];
             });
        vector<vector<int>> ans;
        int x = intervals[0][0];
        int y = intervals[0][1];
        for (auto it : intervals) {
            if (y < it[0]) {
                ans.push_back({x, y});
                x = it[0];
            }
            y = max(y, it[1]);
        }
        ans.push_back({x, y});
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> minimumAbsDifference(vector<int>& arr) {
        sort(arr.begin(), arr.end());
        int n = arr.size();
        int mad = arr[n - 1] - arr[0];
        int i = 1;
        while (i < n) {
            mad = min(mad, arr[i] - arr[i - 1]);
            i++;
        }
        vector<vector<int>> ans;
        i = 1;
        while (i < n) {
            if (arr[i] - arr[i - 1] == mad) {
                ans.push_back({arr[i - 1], arr[i]});
            }
            i++;
        }
        return ans;
    }
};

class Solution {
public:
    vector<string> reorderLogFiles(vector<string>& logs) {
        vector<string> words;
        vector<string> digits;
        for (auto it : logs) {
            int i = it.find(' ');
            if (isalpha(it[i + 1])) {
                words.push_back(it);
            } else {
                digits.push_back(it);
            }
        }
        sort(words.begin(), words.end(), [](string& word1, string& word2) {
            int i = word1.find(' ');
            string p1 = word1.substr(0, i);
            string c1 = word1.substr(i + 1, word1.size() - i - 1);
            int j = word2.find(' ');
            string p2 = word2.substr(0, j);
            string c2 = word2.substr(j + 1, word2.size() - j - 1);
            return c1 == c2 ? p1 < p2 : c1 < c2;
        });
        int i = 0;
        for (auto it : words) {
            logs[i++] = it;
        }
        for (auto it : digits) {
            logs[i++] = it;
        }
        return logs;
    }
};

class Solution {
public:
    string sortSentence(string s) {
        s.push_back(' ');
        int i = 0, n = s.size();
        vector<string> words(10, "");
        while (i < n) {
            int j = i;
            while (s[j] != ' ') {
                j++;
            }
            int k = s[j - 1] - '0';
            words[k] = s.substr(i, j - i - 1);
            i = j + 1;
        }

        string ans = words[1];

        for (int i = 2; i < 10; i++) {
            if (words[i].size() > 0) {
                ans += " " + words[i];
            }
        }
        return ans;
    }
};

class Solution {
public:
    int thirdMax(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        int i = n-1;
        int count = 2;
        while(i > 0){
            if(nums[i-1] == nums[i]){
                i--;
            } else if(nums[i-1] <= nums[i]){
                i--;
                count--;
            }
            if(count == 0){
                return nums[i];
            }
        }
        return nums[n-1];
    }
};

class Solution {
public:
    string triangleType(vector<int>& nums) {
        int a = nums[0];
        int b = nums[1];
        int c = nums[2];

        if (a + b > c && b + c > a && a + c > b) {
            if (a == b || b == c || c == a) {
                if (a == b && b == c) {
                    return "equilateral";
                }
                return "isosceles";
            }
            return "scalene";
        }
        return "none";
    }
};

class MyQueue {
    stack<int> base;
    stack<int> helper;

public:
    MyQueue() {}

    void push(int x) {
        while (!base.empty()) {
            helper.push(base.top());
            base.pop();
        }
        base.push(x);
        while (!helper.empty()) {
            base.push(helper.top());
            helper.pop();
        }
    }

    int pop() {
        while (!base.empty()) {
            helper.push(base.top());
            base.pop();
        }
        int ans = helper.top();
        helper.pop();
        while (!helper.empty()) {
            base.push(helper.top());
            helper.pop();
        }
        return ans;
    }

    int peek() {
        while (!base.empty()) {
            helper.push(base.top());
            base.pop();
        }
        int ans = helper.top();
        while (!helper.empty()) {
            base.push(helper.top());
            helper.pop();
        }
        return ans;
    }

    bool empty() { return base.empty(); }
};

