class FreqStack {
    stack<int> st;
    unordered_map<int, int> freq;
    priority_queue<int> maxf;

public:
    FreqStack() {}

    void push(int val) {
        st.push(val);
        freq[val]++;
        maxf.push(freq[val]);
    }

    int pop() {
        int f = maxf.top();
        maxf.pop();

        int ans = 0;
        stack<int> rev;
        while (!st.empty()) {
            if (freq[st.top()] == f) {
                ans = st.top();
                freq[ans]--;
                st.pop();
                break;
            } else {
                rev.push(st.top());
                st.pop();
            }
        }
        while (!rev.empty()) {
            st.push(rev.top());
            rev.pop();
        }
        return ans;
    }
};

