class MinStack {
    stack<pair<int, int>> st;

public:
    MinStack() {}

    void push(int value) {
        int mini;
        if (st.empty()) {
            mini = value;
        } else {
            mini = st.top().second;
        }
        mini = min(mini, value);
        st.push({value, mini});
    }

    void pop() { st.pop(); }

    int top() { return st.top().first; }

    int getMin() { return st.top().second; }
};

