class Solution {
public:
    string removeDuplicates(string s) {
        stack<char> st;
        for (auto ch : s) {
            if (!st.empty() && st.top() == ch) {
                st.pop();
            } else {
                st.push(ch);
            }
        }
        string ans;
        while (!st.empty()) {
            ans.push_back(st.top());
            st.pop();
        }
        reverse(ans.begin(), ans.end());

        return ans;
    }
};

class Solution {
public:
    bool isValid(string s) {
        stack<char> st;
        for (auto ch : s) {
            if (ch == '(' || ch == '{' || ch == '[') {
                st.push(ch);
            } else if (ch == ')') {
                if (!st.empty() && st.top() == '(') {
                    st.pop();
                } else {
                    return false;
                }
            } else if (ch == '}') {
                if (!st.empty() && st.top() == '{') {
                    st.pop();
                } else {
                    return false;
                }
            } else if (ch == ']') {
                if (!st.empty() && st.top() == '[') {
                    st.pop();
                } else {
                    return false;
                }
            }
        }
        return st.empty();
    }
};

class Solution {
public:
    string addStrings(string num1, string num2) {
        int n = num1.size();
        int m = num2.size();
        while (n < m) {
            num1 = "0" + num1;
            n++;
        }
        while (m < n) {
            num2 = "0" + num2;
            m++;
        }
        string ans = "";
        int carry = 0;
        n--;
        while (n >= 0) {
            carry += num1[n] + num2[n] - '0' - '0';
            ans = to_string(carry % 10) + ans;
            carry /= 10;
            n--;
        }
        if (carry > 0) {
            ans = to_string(carry) + ans;
        }
        return ans;
    }
};

class Solution {
public:
    vector<string> fizzBuzz(int n) {
        vector<string> fizzBuzz;
        for(int i = 1; i <= n; i++){
            if(i%15 == 0){
                fizzBuzz.push_back("FizzBuzz");
            }
            else if(i%5 == 0){
                fizzBuzz.push_back("Buzz");
            }
            else if(i%3 == 0){
                fizzBuzz.push_back("Fizz");
            }
            else{
                fizzBuzz.push_back(to_string(i));
            }
        }

        return fizzBuzz;
    }
};

class Solution {
public:
    int lengthOfLastWord(string s) {
        int n = s.size();
        int j = -1;
        int k = -1;
        int i = n-1;
        while(i >= 0){
            if(s[i] != ' '){
                j = i;
                break;
            }
            i--;
        }
        if(j == -1){
            return 0;
        }
        i = j-1;
        while(i >= 0){
            if(s[i] == ' '){
                k = i;
                break;
            }
            i--;
        }
        return j - k;
    }
};

class Solution {
public:
    string licenseKeyFormatting(string s, int k) {
        string filtered = "";
        for (auto ch : s) {
            if (isalpha(ch)) {
                filtered.push_back(toupper(ch));
            }
            if (isdigit(ch)) {
                filtered.push_back(ch);
            }
        }
        int n = filtered.size();
        if (n == 0) {
            return filtered;
        }
        int i = 0;
        string ans = "";
        while (i < n) {
            int l = n % k;
            if (i > 0) {
                ans += "-";
            }
            if (i > 0 || l == 0) {
                l = k;
            }
            ans += filtered.substr(i, l);
            i += l;
        }
        return ans;
    }
};

class Solution {
public:
    bool rotateString(string s, string goal) {
        int n = s.size();
        int i = 0;

        while (i < n) {
            string temp = s.substr(1, n - 1);
            temp.push_back(s[0]);
            s = temp;
            if (s == goal) {
                return true;
            }
            i++;
        }
        return false;
    }
};

