////////////////////////////////////////////////////////////

class MedianFinder {
    priority_queue<int> first;
    priority_queue<int, vector<int>, greater<int>> second;

public:
    MedianFinder() {}

    void addNum(int num) {
        second.push(num);

        while (first.size() < second.size()) {
            first.push(second.top());
            second.pop();
        }
        while (!second.empty() && first.top() > second.top()) {
            first.push(second.top());
            second.pop();
            second.push(first.top());
            first.pop();
        }
    }

    double findMedian() {
        if (first.size() == second.size()) {
            double ans = first.top() + second.top();
            ans /= 2;

            return ans;
        }
        return first.top();
    }
};

