class Solution {
public:
    int transform(int n) {
        int sum = 0;
        while (n > 0) {
            sum += (n % 10) * (n % 10);
            n /= 10;
        }
        return sum;
    }
    bool isHappy(int n) {
        unordered_map<int, bool> mp;
        mp[n] = true;
        while (n != 1) {
            n = transform(n);
            if (mp.contains(n) && mp[n]) {
                break;
            } else {
                mp[n] = true;
            }
        }
        return mp.contains(1) && mp[1];
    }
};

class Solution {
public:
    void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
        vector<int> ans(n + m, 0);
        int i = 0, j = 0, k = 0;
        while (i < m && j < n) {
            if (nums1[i] < nums2[j]) {
                ans[k++] = nums1[i++];
            } else {
                ans[k++] = nums2[j++];
            }
        }
        while (i < m) {
            ans[k++] = nums1[i++];
        }
        while (j < n) {
            ans[k++] = nums2[j++];
        }
        k = 0;
        for (auto it : ans) {
            nums1[k++] = it;
        }
    }
};

class Solution {
public:
    int removeElement(vector<int>& nums, int val) {
        int i = 0, j = nums.size() - 1, k = 0;
        while (i < j) {
            if (nums[i] == val && nums[j] != val) {
                int temp = nums[i];
                nums[i] = nums[j];
                nums[j] = temp;
            }
            while (nums[i] != val) {
                i++;
            }
            while (nums[j] == val) {
                j--;
            }
        }
        while (nums[k] != val) {
            k++;
        }
        return k;
    }
};
